import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第二十七卦 颐 山雷颐 艮上震下","description":"周易 - 第二十七卦 颐 山雷颐 艮上震下","frontmatter":{"title":"第二十七卦 颐 山雷颐 艮上震下","description":"周易 - 第二十七卦 颐 山雷颐 艮上震下"},"headers":[],"relativePath":"zh/classics/zhouyi/028.md","filePath":"zh/classics/zhouyi/028.md"}'),l={name:"zh/classics/zhouyi/028.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="颐" tabindex="-1">颐 <a class="header-anchor" href="#颐" aria-label="Permalink to “颐”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>贞吉。观颐，自求口实。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>颐贞吉，养正则吉也。观颐，观其所养也；自求口实，观其自养也。天地养万物，圣人养贤，以及万民；颐之时义大矣哉！</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>山下有雷，颐；君子以慎言语，节饮食。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>舍尔灵龟，观我朵颐，凶。象 曰：观我朵颐，亦不足贵也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>颠颐，拂经，于丘颐，征凶。象曰：六二征凶，行失类也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>拂颐，贞凶，十年勿用，无攸利。象曰：十年勿用，道大悖也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>颠颐吉，虎视眈眈，其欲逐逐，无咎。象曰：颠颐之吉，上施光也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>拂经，居贞吉，不可涉大川。象曰：居贞之吉，顺以从上也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>由颐，厉吉，利涉大川。象曰：由颐厉吉，大有庆也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
